class Solution { public int maximizeTheProfit(int n,List<List<Integer>> offers){offers.sort(Comparator.comparingInt(offer->offer.get(1)));int[] dp=new int[n+1];int index=0;for(int end=0;end<n;end++){dp[end+1]=Math.max(dp[end+1],dp[end]);while(index<offers.size()&&offers.get(index).get(1)==end){List<Integer> offer=offers.get(index++);dp[end+1]=Math.max(dp[end+1],dp[offer.get(0)]+offer.get(2));}}return dp[n];} }
